package com.yeyamo_mobile.api.referral_service.infrastructure.persistence;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import jakarta.persistence.LockModeType;
public interface ReferralCodeRepository extends JpaRepository<ReferralCodeEntity,UUID>{Optional<ReferralCodeEntity>findByCodeIgnoreCase(String code);List<ReferralCodeEntity>findByOwnerUserIdOrderByCreatedAtDesc(String owner);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select c from ReferralCodeEntity c where upper(c.code)=upper(:code)")Optional<ReferralCodeEntity>findLockedByCode(@Param("code")String code);}
